mapper.select:
SELECT a.id AS value,REPLACE(a.index_name,'告警次数','') AS label FROM system_docking.api_platform_index_info a LEFT JOIN system_docking.api_interface_system_platform_info b ON a.platform_id=b.id LEFT JOIN system_docking.api_interface_system_info c ON b.system_id=c.id WHERE a.is_enable='1' AND b.is_enable='1' AND c.is_enable='1' AND a.is_monitor='1'
AND c.system_code = #{params.type}
AND a.index_type = #{params.index_type}

select.if:
SELECT DISTINCT a.ID AS value,CONCAT(a.resource_desc,'(',f.ip_address,')') AS label FROM system_docking.api_system_resource a LEFT JOIN system_docking.api_system_index_resource b ON a.ID=b.resource_id LEFT JOIN system_docking.api_platform_index_info c ON b.index_id=c.ID LEFT JOIN system_docking.api_interface_system_platform_info d ON c.platform_id=d.ID LEFT JOIN system_docking.api_interface_system_info e ON d.system_id=e.ID LEFT JOIN system_docking.api_system_resource_ip f ON a.ID=f.resource_id WHERE a.is_enable='1' AND c.is_enable='1' AND d.is_enable='1' AND e.is_enable='1'
AND c.ID=#{params.indicators}
AND e.system_code = #{params.type}
ORDER BY label

SELECT DISTINCT a.resource_code AS value,a.resource_desc AS label FROM system_docking.api_system_resource a LEFT JOIN system_docking.api_interface_system_platform_info b ON a.platform_id=b.ID LEFT JOIN system_docking.api_platform_index_info c ON b.ID=c.platform_id LEFT JOIN system_docking.api_interface_system_info d ON b.system_id=d.ID WHERE a.is_enable='1' AND b.is_enable='1' AND d.is_enable='1'
AND c.ID=#{params.indicators}
AND d.system_code = #{params.type}
ORDER BY label

mapper.select:
SELECT count(1)
FROM system_docking.api_prediction_threshold_info a
WHERE 1=1

    AND a.index_id = #{params.indicators}


    AND a.business_type=#{params.business_type}

SELECT a.id,a.index_id,REPLACE(a.index_name,'告警次数','') AS index_name,a.data_type,a.resource,a.resource_name,a.business_type,a.threshold_type,a.operator,a.operator_value,a.description,
CASE WHEN threshold_type = '0' THEN CONCAT('预测值与实际值差距超过',operator_value)
WHEN threshold_type = '1' THEN CONCAT('预测值与实际值差距超过',operator_value,'%')
ELSE '' END AS threshold_parameter
FROM system_docking.api_prediction_threshold_info a
WHERE 1=1

    AND a.index_id = #{params.indicators}


    AND a.business_type=#{params.business_type}


    LIMIT ${params.rows} OFFSET ${params.page}
